import logging, math, bisect, mcu
from . import creality_ldc1612, probe, manual_probe

def calc_determinant(matrix):
    m = matrix
    aei = m[0][0] * m[1][1] * m[2][2]
    bfg = m[1][0] * m[2][1] * m[0][2]
    cdh = m[2][0] * m[0][1] * m[1][2]
    ceg = m[2][0] * m[1][1] * m[0][2]
    bdi = m[1][0] * m[0][1] * m[2][2]
    afh = m[0][0] * m[2][1] * m[1][2]
    return aei + bfg + cdh - ceg - bdi - afh


class Polynomial2d:

    def __init__(self, a, b, c):
        self.a = a
        self.b = b
        self.c = c

    def __call__(self, xval):
        return self.c * xval * xval + self.b * xval + self.a

    def get_coefs(self):
        return (
         self.a, self.b, self.c)

    def __str__(self):
        return "%f, %f, %f" % (self.a, self.b, self.c)

    def __repr__(self):
        parts = [
         "y(x) ="]
        deg = 2
        for (i, coef) in enumerate((self.c, self.b, self.a)):
            if round(coef, 8) == int(coef):
                coef == int(coef)
            if abs(coef) < 1e-10:
                pass
            else:
                cur_deg = deg - i
                x_str = "x^%d" % (cur_deg,) if cur_deg > 1 else "x" * cur_deg
                if len(parts) == 1:
                    parts.append("%f%s" % (coef, x_str))
                else:
                    sym = "-" if coef < 0 else "+"
                    parts.append("%s %f%s" % (sym, abs(coef), x_str))
            return " ".join(parts)

    @classmethod
    def fit(cls, coords):
        xlist = [c[0] for c in coords]
        ylist = [c[1] for c in coords]
        count = len(coords)
        sum_x = sum(xlist)
        sum_y = sum(ylist)
        sum_x2 = sum([x ** 2 for x in xlist])
        sum_x3 = sum([x ** 3 for x in xlist])
        sum_x4 = sum([x ** 4 for x in xlist])
        sum_xy = sum([x * y for x, y in coords])
        sum_x2y = sum([y * x ** 2 for x, y in coords])
        vector_b = [sum_y, sum_xy, sum_x2y]
        m = [
         [
          count, sum_x, sum_x2],
         [
          sum_x, sum_x2, sum_x3],
         [
          sum_x2, sum_x3, sum_x4]]
        m0 = [
         vector_b, m[1], m[2]]
        m1 = [m[0], vector_b, m[2]]
        m2 = [m[0], m[1], vector_b]
        det_m = calc_determinant(m)
        a0 = calc_determinant(m0) / det_m
        a1 = calc_determinant(m1) / det_m
        a2 = calc_determinant(m2) / det_m
        return cls(a0, a1, a2)


class CurrentCalibration:

    def __init__(self, config):
        self.printer = config.get_printer()
        self.name = config.get_name()
        self.drift_comp = CurrentDriftCompensation(config)
        self.zero_auto_probe = config.getboolean("zero_auto_probe", False)
        self.cal_freqs = []
        self.cal_zpos = []
        self.cal_temp = config.getfloat("calibration_temp", 0)
        cal = config.get("calibrate", None)
        if cal is not None:
            cal = [list(map(float, d.strip().split(":", 1))) for d in cal.split(",")]
            self.load_calibration(cal)
        self.probe_speed = 0.0
        self.gcode = self.printer.lookup_object("gcode")
        self.gcode.register_command("PROBE_CURRENT_CALIBRATE", (self.cmd_CURRENT_CALIBRATE),
          desc=(self.cmd_CURRENT_CALIBRATE_help))

    def is_calibrated(self):
        return len(self.cal_freqs) > 2

    def load_calibration(self, cal):
        cal = sorted([(c[1], c[0]) for c in cal])
        self.cal_freqs = [c[0] for c in cal]
        self.cal_zpos = [c[1] for c in cal]

    def apply_calibration(self, samples):
        for (i, (samp_time, freq, dummy_z)) in enumerate(samples):
            adj_freq = self.drift_comp.adjust_freq(freq, self.cal_temp)
            pos = bisect.bisect(self.cal_freqs, adj_freq)
            if pos >= len(self.cal_zpos):
                zpos = -99.9
            elif pos == 0:
                zpos = 99.9
            else:
                this_freq = self.cal_freqs[pos]
                prev_freq = self.cal_freqs[pos - 1]
                this_zpos = self.cal_zpos[pos]
                prev_zpos = self.cal_zpos[pos - 1]
                gain = (this_zpos - prev_zpos) / (this_freq - prev_freq)
                offset = prev_zpos - prev_freq * gain
                zpos = adj_freq * gain + offset
            samples[i] = (
             samp_time, freq, round(zpos, 6))

    def height_to_freq(self, height):
        rev_zpos = list(reversed(self.cal_zpos))
        rev_freqs = list(reversed(self.cal_freqs))
        pos = bisect.bisect(rev_zpos, height)
        if pos == 0 or pos >= len(rev_zpos):
            raise self.printer.command_error("Invalid probe_current height")
        this_freq = rev_freqs[pos]
        prev_freq = rev_freqs[pos - 1]
        this_zpos = rev_zpos[pos]
        prev_zpos = rev_zpos[pos - 1]
        gain = (this_freq - prev_freq) / (this_zpos - prev_zpos)
        offset = prev_freq - prev_zpos * gain
        freq = height * gain + offset
        return self.drift_comp.lookup_freq(freq, self.cal_temp)

    def do_calibration_moves(self, move_speed):
        toolhead = self.printer.lookup_object("toolhead")
        kin = toolhead.get_kinematics()
        move = toolhead.manual_move
        msgs = []
        is_finished = False

        def handle_batch(msg):
            if is_finished:
                return False
            msgs.append(msg)
            return True

        self.printer.lookup_object(self.name).add_client(handle_batch)
        toolhead.dwell(1.0)
        temp = self.drift_comp.get_temperature()
        max_z = 4
        samp_dist = 0.05
        num_steps = int(max_z / samp_dist + 0.5) + 1
        start_pos = toolhead.get_position()
        times = []
        for i in range(num_steps):
            hop_pos = list(start_pos)
            hop_pos[2] += i * samp_dist + 0.5
            move(hop_pos, move_speed)
            next_pos = list(start_pos)
            next_pos[2] += i * samp_dist
            move(next_pos, move_speed)
            start_query_time = toolhead.get_last_move_time() + 0.05
            end_query_time = start_query_time + 0.1
            toolhead.dwell(0.2)
            toolhead.flush_step_generation()
            kin_spos = {s.get_name(): s.get_commanded_position() for s in kin.get_steppers()}
            kin_pos = kin.calc_position(kin_spos)
            times.append((start_query_time, end_query_time, kin_pos[2]))

        toolhead.dwell(1.0)
        toolhead.wait_moves()
        temp = (temp + self.drift_comp.get_temperature()) / 2.0
        is_finished = True
        cal = {}
        step = 0
        for msg in msgs:
            for (query_time, freq, old_z) in msg["data"]:
                while True:
                    if step < len(times) and query_time > times[step][1]:
                        step += 1

                if step < len(times):
                    if query_time >= times[step][0]:
                        cal.setdefault(times[step][2], []).append(freq)

        if len(cal) != len(times):
            raise self.printer.command_error("Failed calibration - incomplete sensor data")
        return (cal, temp)

    def calc_freqs(self, meas):
        total_count = total_variance = 0
        positions = {}
        for (pos, freqs) in meas.items():
            count = len(freqs)
            freq_avg = float(sum(freqs)) / count
            positions[pos] = freq_avg
            total_count += count
            total_variance += sum([(f - freq_avg) ** 2 for f in freqs])

        return (positions, math.sqrt(total_variance / total_count), total_count)

    def post_manual_probe(self, kin_pos):
        if kin_pos is None:
            return
        curpos = list(kin_pos)
        move = self.printer.lookup_object("toolhead").manual_move
        probe_calibrate_z = curpos[2]
        curpos[2] += 5.0
        move(curpos, self.probe_speed)
        pprobe = self.printer.lookup_object("probe")
        (x_offset, y_offset, z_offset) = pprobe.get_offsets()
        curpos[0] -= x_offset
        curpos[1] -= y_offset
        move(curpos, self.probe_speed)
        curpos[2] -= 4.95
        move(curpos, self.probe_speed)
        (cal, temp) = self.do_calibration_moves(self.probe_speed)
        (positions, std, total) = self.calc_freqs(cal)
        last_freq = 0.0
        for (pos, freq) in reversed(sorted(positions.items())):
            if freq <= last_freq:
                raise self.printer.command_error("Failed calibration - frequency not increasing each step")
            else:
                last_freq = freq

        gcode = self.printer.lookup_object("gcode")
        gcode.respond_info("probe_current: stddev=%.3f in %d queries\nThe SAVE_CONFIG command will update the printer config file\nand restart the printer." % (
         std, total))
        cal_contents = []
        for (i, (pos, freq)) in enumerate(sorted(positions.items())):
            if not i % 3:
                cal_contents.append("\n")
            cal_contents.append("%.6f:%.3f" % (pos - probe_calibrate_z, freq))
            cal_contents.append(",")

        cal_contents.pop()
        configfile = self.printer.lookup_object("configfile")
        configfile.set(self.name, "calibrate", "".join(cal_contents))
        configfile.set(self.name, "calibration_temp", "%.6f" % (temp,))

    cmd_CURRENT_CALIBRATE_help = "Calibrate current current probe"

    def cmd_CURRENT_CALIBRATE(self, gcmd):
        self.probe_speed = gcmd.get_float("PROBE_SPEED", 5.0, above=0.0)
        toolhead = self.printer.lookup_object("toolhead")
        if self.zero_auto_probe is True:
            multi_prober = self.printer.lookup_object("creality_multi_probe")
            if multi_prober is None:
                raise gcmd.error("Config object 'creality_multi_probe' must be specified")
            gcode = self.printer.lookup_object("gcode")
            gcode.run_script_from_command("G28")
            gcode.run_script_from_command("G1 Z15 F600")
            gcode.run_script_from_command("LDC_CALIBRATE_DRIVE_CURRENT")
            kin_pos = multi_prober.probe("G28 Z")
            self.post_manual_probe(kin_pos)
            gcode.run_script_from_command("SAVE_CONFIG_NORESTART")
        else:
            curtime = self.printer.get_reactor().monotonic()
            if "xy" not in toolhead.get_status(curtime)["homed_axes"]:
                raise self.printer.command_error("Must home X and Y before probe")
            if "z" not in toolhead.get_status(curtime)["homed_axes"]:
                pos = toolhead.get_position()
                pos[2] = toolhead.get_status(curtime)["axis_maximum"][2]
                toolhead.set_position(pos, homing_axes=[2])
            manual_probe.ManualProbeHelper(self.printer, gcmd, self.post_manual_probe)


class CurrentEndstopWrapper:
    HAS_SCANNING = True

    def __init__(self, config, sensor_helper, calibration):
        self._printer = config.get_printer()
        self._sensor_helper = sensor_helper
        self._mcu = sensor_helper.get_mcu()
        self._calibration = calibration
        self._z_offset = config.getfloat("z_offset", minval=0.0)
        self.mcu_endstop = None
        if sensor_helper.endstop_pin is None:
            self._dispatch = mcu.TriggerDispatch(self._mcu)
        else:
            pin_params = sensor_helper.endstop_pin_params
            self.mcu_endstop = pin_params["chip"].setup_pin("endstop", pin_params)
        self._samples = []
        self._is_sampling = self._start_from_home = self._need_stop = False
        self._trigger_time = 0.0
        self._printer.register_event_handler("klippy:mcu_identify", self._handle_mcu_identify)

    def _handle_mcu_identify(self):
        kin = self._printer.lookup_object("toolhead").get_kinematics()
        for stepper in kin.get_steppers():
            if stepper.is_active_axis("z"):
                self.add_stepper(stepper)

    def _start_measurements(self, is_home=False):
        self._need_stop = False
        if self._is_sampling:
            return
        self._is_sampling = True
        self._is_from_home = is_home
        self._sensor_helper.add_client(self._add_measurement)

    def _stop_measurements(self, is_home=False):
        if self._is_sampling:
            if not (is_home and self._start_from_home):
                return
        self._need_stop = True

    def _add_measurement(self, msg):
        if self._need_stop:
            del self._samples[:]
            self._is_sampling = self._need_stop = False
            return False
        self._samples.append(msg)
        return True

    def get_mcu(self):
        if self.mcu_endstop is None:
            return self._mcu
        return self.mcu_endstop.get_mcu()

    def add_stepper(self, stepper):
        if self.mcu_endstop is None:
            self._dispatch.add_stepper(stepper)
        else:
            self.mcu_endstop.add_stepper(stepper)

    def get_steppers(self):
        if self.mcu_endstop is None:
            return self._dispatch.get_steppers()
        return self.mcu_endstop.get_steppers()

    def home_start(self, print_time, sample_time, sample_count, rest_time, triggered=True):
        self._trigger_time = 0.0
        self._start_measurements(is_home=True)
        trigger_freq = self._calibration.height_to_freq(self._z_offset)
        if self.mcu_endstop is None:
            trigger_completion = self._dispatch.start(print_time)
            self._sensor_helper.setup_home(print_time, trigger_freq, self._dispatch.get_oid(), mcu.MCU_trsync.REASON_ENDSTOP_HIT)
        else:
            trigger_completion = self.mcu_endstop.home_start(print_time, sample_time, sample_count, rest_time, triggered)
            self._sensor_helper.setup_home(print_time, trigger_freq, 0, 0)
        return trigger_completion

    def home_wait(self, home_end_time):
        if self.mcu_endstop is None:
            self._dispatch.wait_end(home_end_time)
            trigger_time = self._sensor_helper.clear_home()
            self._stop_measurements(is_home=True)
            res = self._dispatch.stop()
            if res == mcu.MCU_trsync.REASON_COMMS_TIMEOUT:
                return -1.0
            if res != mcu.MCU_trsync.REASON_ENDSTOP_HIT:
                return 0.0
            if self._mcu.is_fileoutput():
                return home_end_time
            self._trigger_time = trigger_time
            return trigger_time
        self._sensor_helper.clear_home()
        self._stop_measurements(is_home=True)
        self._trigger_time = self.mcu_endstop.home_wait(home_end_time)
        return self._trigger_time

    def query_endstop(self, print_time):
        if self.mcu_endstop is None:
            return False
        return self.mcu_endstop.query_endstop(print_time)

    def probing_move(self, pos, speed):
        phoming = self._printer.lookup_object("homing")
        trig_pos = phoming.probing_move(self, pos, speed)
        if not self._trigger_time:
            return trig_pos
        reactor = self._printer.get_reactor()
        while True:
            systime = reactor.monotonic()
            est_print_time = self._mcu.estimated_print_time(systime)
            need_delay = self._trigger_time + 0.2 - est_print_time
            if need_delay <= 0.0:
                break
            else:
                reactor.pause(systime + need_delay)

        samples = self._samples
        self._samples = []
        start_time = self._trigger_time + 0.05
        end_time = start_time + 0.1
        samp_sum = 0.0
        samp_count = 0
        for msg in samples:
            data = msg["data"]
            if data[0][0] > end_time:
                break
            if data[-1][0] < start_time:
                pass
            else:
                for (time, freq, z) in data:
                    if time >= start_time:
                        if time <= end_time:
                            samp_sum += z
                            samp_count += 1

        if not samp_count:
            raise self._printer.command_error("Unable to obtain probe_current sensor readings")
        halt_z = samp_sum / samp_count
        toolhead = self._printer.lookup_object("toolhead")
        new_pos = toolhead.get_position()
        new_pos[2] += self._z_offset - halt_z
        return new_pos

    def multi_probe_begin(self):
        if not self._calibration.is_calibrated():
            raise self._printer.command_error("Must calibrate probe_current first")
        self._start_measurements()

    def multi_probe_end(self):
        self._stop_measurements()

    def probe_prepare(self, hmove):
        pass

    def probe_finish(self, hmove):
        pass

    def get_position_endstop(self):
        return self._z_offset


class PrinterCurrentProbe:

    def __init__(self, config):
        self.name = config.get_name()
        self.printer = config.get_printer()
        self.reactor = self.printer.get_reactor()
        self.calibration = CurrentCalibration(config)
        sensors = {"ldc1612": (creality_ldc1612.LDC1612)}
        sensor_type = config.getchoice("sensor_type", {s: s for s in sensors})
        self.sensor_helper = sensors[sensor_type](config, self.calibration)
        self.mcu_probe = CurrentEndstopWrapper(config, self.sensor_helper, self.calibration)
        self.cmd_helper = probe.ProbeCommandHelper(config, self, self.mcu_probe.query_endstop)
        self.probe_offsets = probe.ProbeOffsetsHelper(config)
        self.probe_session = probe.ProbeSessionHelper(config, self.mcu_probe)
        self.printer.add_object("probe", self)
        self.toolhead = None
        self.printer.register_event_handler("klippy:connect", self.handle_connect)
        self.printer.register_event_handler("stepper_enable:motor_off", self.event_motor_off)
        self.gcode_move = self.printer.load_object(config, "gcode_move")
        self.real_z = 0.0
        self.z_scaning = False
        self.z_printing = False
        self.z_last = 0.0
        self.sync_timer = None
        self.gcode = self.printer.lookup_object("gcode")
        self.gcode.register_command("PROBE_CURRENT_REAL_PRINT_START", (self.cmd_CURRENT_REAL_PRINT_START), desc=(self.cmd_CURRENT_REAL_PRINT_START_help))
        self.gcode.register_command("PROBE_CURRENT_REAL_PRINT_END", (self.cmd_CURRENT_REAL_PRINT_END), desc=(self.cmd_CURRENT_REAL_PRINT_END_help))
        self.gcode.register_command("PROBE_CURRENT_REAL_CALIBRATE_START", (self.cmd_CURRENT_REAL_CALIBRATE_START), desc=(self.cmd_CURRENT_REAL_CALIBRATE_START_help))
        self.gcode.register_command("PROBE_CURRENT_REAL_CALIBRATE_END", (self.cmd_CURRENT_REAL_CALIBRATE_END), desc=(self.cmd_CURRENT_REAL_CALIBRATE_END_help))

    def get_probe_params(self, gcmd=None):
        return self.probe_session.get_probe_params(gcmd)

    def get_offsets(self):
        return self.probe_offsets.get_offsets()

    def get_status(self, eventtime):
        return self.cmd_helper.get_status(eventtime)

    def start_probe_session(self, gcmd):
        return self.probe_session.start_probe_session(gcmd)

    def get_probe_name(self):
        return self.name

    def get_lift_speed(self, gcmd):
        return self.probe_session.lift_speed

    def get_probe_speed(self, gcmd):
        if gcmd is not None:
            return gcmd.get_float("PROBE_SPEED", (self.probe_session.speed), above=0.0)
        return self.probe_session.speed

    def handle_connect(self):
        self.toolhead = self.printer.lookup_object("toolhead")
        if self.sensor_helper.real_adjust_is_valid():
            self.sensor_helper.real_adjust_setup()

    def set_interval(self, interval):
        self.sensor_helper.set_interval(interval)

    def add_client(self, cb):
        self.sensor_helper.add_client(cb)

    def stream(self, cb):
        return StreamingContext(self, cb)

    def event_motor_off(self, print_time):
        if self.sensor_helper.real_adjust_is_enable():
            self.sensor_helper.real_adjust_stop()

    def get_temp(self):
        return self.calibration.drift_comp.get_temperature()

    def get_position(self):
        return self.toolhead.get_position()

    def move(self, newpos, speed):
        self.z_last = newpos[2]
        self.toolhead.move(newpos, speed)

    def get_z_real(self):
        return (
         self.z_scaning, self.real_z)

    def scan_data_collected(self, msg):
        data = msg["data"]
        valid_samples = []
        for (ptime, _, z) in data:
            if not z > 99.0:
                if z < -99.0:
                    pass
                else:
                    valid_samples.append(z)
                sample_len = len(valid_samples)

        if sample_len == 0:
            return self.z_scaning
        z_height = sum([s for s in valid_samples]) / sample_len
        self.real_z = z_height
        if self.z_printing:
            self.gcode.respond_info("current z_real: %f\n" % z_height)
        elif self.z_scaning:
            self.sensor_helper.real_adjust_sync(self.real_z, self.get_temp())
        return self.z_scaning

    def check_home(self):
        kin = self.toolhead.get_kinematics()
        for i in (0, 1, 2):
            if kin.limits[i][0] > kin.limits[i][1]:
                raise self.printer.command_error("Must home axis first")

    def _sync_event(self, eventtime):
        if self.z_scaning:
            self.sensor_helper.real_adjust_sync(1.0, self.get_temp())
        return eventtime + 1.0

    cmd_CURRENT_REAL_PRINT_START_help = "Realtime print current scan height start"

    def cmd_CURRENT_REAL_PRINT_START(self, gcmd):
        interval = float(gcmd.get("INTERVAL", creality_ldc1612.BATCH_UPDATES))
        self.z_scaning = True
        self.z_printing = True
        self.set_interval(interval)
        self.add_client(self.scan_data_collected)

    cmd_CURRENT_REAL_PRINT_END_help = "Realtime print current scan height end"

    def cmd_CURRENT_REAL_PRINT_END(self, gcmd):
        self.z_scaning = False

    cmd_CURRENT_REAL_CALIBRATE_START_help = "Realtime scan height current probe start"

    def cmd_CURRENT_REAL_CALIBRATE_START(self, gcmd):
        self.check_home()
        if not self.sensor_helper.real_adjust_is_valid():
            gcmd.respond_info("real adjust is invalid")
            return
        interval = float(gcmd.get("INTERVAL", creality_ldc1612.BATCH_UPDATES))
        gcmd.respond_info("Beginning real calibrate, sync interval: %f(s)" % interval)
        self.z_scaning = True
        self.z_printing = False
        self.z_last = self.gcode_move.last_position[2]
        self.real_z = self.z_last
        self.gcode_move.set_move_transform(self, True)
        self.set_interval(interval)
        if not self.sensor_helper.real_adjust_is_async_mcu():
            self.sync_timer = self.reactor.register_timer(self._sync_event, self.reactor.NOW)
        self.add_client(self.scan_data_collected)

    cmd_CURRENT_REAL_CALIBRATE_END_help = "Realtime scan height current probe end"

    def cmd_CURRENT_REAL_CALIBRATE_END(self, gcmd):
        if not self.sensor_helper.real_adjust_is_valid():
            gcmd.respond_info("real adjust is invalid")
            return
        self.z_scaning = False
        if not self.sensor_helper.real_adjust_is_async_mcu():
            self.reactor.unregister_timer(self.sync_timer)
        self.sensor_helper.real_adjust_stop()
        self.set_interval(creality_ldc1612.BATCH_UPDATES)
        self.gcode_move.set_move_transform(self.toolhead, True)
        gcmd.respond_info("Ending real calibrate, resume interval: %f(s)" % creality_ldc1612.BATCH_UPDATES)


DRIFT_SAMPLE_COUNT = 9

class CurrentDriftCompensation:

    def __init__(self, config):
        self.printer = config.get_printer()
        self.name = config.get_name()
        self.drift_calibration = None
        self.calibration_samples = None
        self.dc_min_temp = config.getfloat("drift_calibration_min_temp", 0.0)
        dc = config.getlists("drift_calibration",
          None, seps=(',', '\n'), parser=float)
        self.min_freq = 999999999999.0
        if dc is not None:
            for coefs in dc:
                if len(coefs) != 3:
                    raise config.error("Invalid polynomial in drift calibration")
                self.drift_calibration = [Polynomial2d(*coefs) for coefs in dc]
                cal = self.drift_calibration
                self._check_calibration(cal, self.dc_min_temp, config.error)
                low_poly = self.drift_calibration[-1]
                self.min_freq = min([low_poly(temp) for temp in range(121)])
                cal_str = "\n".join([repr(p) for p in cal])
                logging.info("%s: loaded temperature drift calibration. Min Temp: %.2f, Min Freq: %.6f\n%s" % (
                 self.name, self.dc_min_temp, self.min_freq, cal_str))

        else:
            logging.info("%s: No drift calibration configured, disabling temperature compensation" % (
             self.name,))
        self.enabled = has_dc = self.drift_calibration is not None
        cal_temp = config.getfloat("calibration_temp", 0)
        if cal_temp < 1e-06:
            if has_dc:
                self.enabled = False
                logging.info("%s: No temperature saved for current probe calibration, disabling temperature compensation." % (
                 self.name,))
            temp_section = "creality_temperature_probe"
            self.temp_sensor = None
            if config.has_section(temp_section):
                self.temp_sensor = self.printer.load_object(config, temp_section)
                self.temp_sensor.register_calibration_helper(self)
            if self.temp_sensor is None:
                if has_dc:
                    self.enabled = False
                    logging.info("%s: Temperature Sensor [%s] not configured, disabling temperature compensation" % (
                     self.name, temp_section))

    def is_enabled(self):
        return self.enabled

    def collect_sample(self, kin_pos, tool_zero_z, speeds):
        if self.calibration_samples is None:
            self.calibration_samples = [[] for _ in range(DRIFT_SAMPLE_COUNT)]
        move_times = []
        probe_samples = [[] for _ in range(DRIFT_SAMPLE_COUNT)]
        scanner = self.printer.lookup_object(self.name)
        toolhead = self.printer.lookup_object("toolhead")
        reactor = self.printer.get_reactor()
        cur_pos = toolhead.get_position()
        sample_temp = self.get_temperature()
        (lift_speed, probe_speed, _) = speeds

        def _on_data_recd(msg):
            data = msg["data"]
            if not move_times:
                return
            (idx, start_time, end_time) = move_times[0]
            for sample in data:
                ptime = sample[0]
                while ptime > end_time:
                    move_times.pop(0)
                    if not move_times:
                        return None
                    else:
                        (idx, start_time, end_time) = move_times[0]

                if ptime < start_time:
                    pass
                else:
                    probe_samples[idx].append(sample)

        with scanner.stream(_on_data_recd):
            for i in range(DRIFT_SAMPLE_COUNT):
                if i == 0:
                    cur_pos[2] = tool_zero_z + 0.05
                else:
                    cur_pos[2] += 1.0
                    toolhead.manual_move(cur_pos, lift_speed)
                    cur_pos[2] -= 0.5
                toolhead.manual_move(cur_pos, probe_speed)
                start = toolhead.get_last_move_time() + 0.05
                end = start + 0.1
                move_times.append((i, start, end))
                toolhead.dwell(0.2)

            toolhead.wait_moves()
            sample_temp = (sample_temp + self.get_temperature()) / 2.0
            reactor.pause(reactor.monotonic() + 0.2)
        for (i, data) in enumerate(probe_samples):
            freqs = [d[1] for d in data]
            zvals = [d[2] for d in data]
            avg_freq = sum(freqs) / len(freqs)
            avg_z = sum(zvals) / len(zvals)
            kin_z = i * 0.5 + 0.05 + kin_pos[2]
            logging.info("Probe Values at Temp %.2fC, Z %.4fmm: Avg Freq = %.6f, Avg Measured Z = %.6f" % (
             sample_temp, kin_z, avg_freq, avg_z))
            self.calibration_samples[i].append((sample_temp, avg_freq))

        return sample_temp

    def start_calibration(self):
        self.calibration_samples = [[] for _ in range(DRIFT_SAMPLE_COUNT)]

    def finish_calibration(self, success):
        cal_samples = self.calibration_samples
        self.calibration_samples = None
        if not success:
            return
        gcode = self.printer.lookup_object("gcode")
        if len(cal_samples) < 3:
            raise gcode.error("calbration error, not enough samples")
        (min_temp, _) = cal_samples[0][0]
        polynomials = []
        for (i, coords) in enumerate(cal_samples):
            height = 0.05 + i * 0.5
            poly = Polynomial2d.fit(coords)
            polynomials.append(poly)
            logging.info("Polynomial at Z=%.2f: %s" % (height, repr(poly)))

        self._check_calibration(polynomials, min_temp)
        coef_cfg = "\n" + "\n".join([str(p) for p in polynomials])
        configfile = self.printer.lookup_object("configfile")
        configfile.set(self.name, "drift_calibration", coef_cfg)
        configfile.set(self.name, "drift_calibration_min_temp", min_temp)
        gcode.respond_info("%s: generated %d 2D polynomials\nThe SAVE_CONFIG command will update the printer config file and restart the printer." % (
         self.name, len(polynomials)))
        try:
            import json
            ctime = int(self.printer.get_reactor().monotonic())
            tmpfname = "/tmp/current-probe-drift-%d.json" % ctime
            out = {'polynomial_coefs':[c.get_coefs() for c in polynomials], 
             'legend':[
              "temperature", "frequency"], 
             'data':cal_samples, 
             'start_z':0.05, 
             'sample_z_dist':0.5}
            with open(tmpfname, "w") as f:
                f.write(json.dumps(out))
        except Exception:
            logging.exception("Failed to write %s" % tmpfname)

    def _check_calibration(self, calibration, start_temp, error=None):
        error = error or self.printer.command_error
        start = int(start_temp)
        for temp in range(start, 121, 1):
            last_freq = calibration[0](temp)
            for (i, poly) in enumerate(calibration[1:]):
                next_freq = poly(temp)
                if next_freq >= last_freq:
                    raise error("%s: invalid calibration detected, curve at index %d overlaps previous curve at temp %dC." % (
                     self.name, i + 1, temp))
                else:
                    last_freq = next_freq

    def adjust_freq(self, freq, dest_temp):
        if not self.enabled or freq < self.min_freq:
            return freq
        cur_temp = self.temp_sensor.get_temp()[0]
        return self._calc_freq(freq, cur_temp, dest_temp)

    def lookup_freq(self, freq, origin_temp):
        if not self.enabled or freq < self.min_freq:
            return freq
        cur_temp = self.temp_sensor.get_temp()[0]
        return self._calc_freq(freq, origin_temp, cur_temp)

    def _calc_freq(self, freq, origin_temp, dest_temp):
        high_freq = low_freq = None
        dc = self.drift_calibration
        for (pos, poly) in enumerate(dc):
            high_freq = low_freq
            low_freq = poly(origin_temp)
            if freq >= low_freq:
                if high_freq is None:
                    return dc[0](dest_temp)
                else:
                    t = min(1.0, max(0.0, (freq - low_freq) / (high_freq - low_freq)))
                    low_tgt_freq = poly(dest_temp)
                    high_tgt_freq = dc[pos - 1](dest_temp)
                    return (1 - t) * low_tgt_freq + t * high_tgt_freq
            return freq

    def get_temperature(self):
        if self.temp_sensor is not None:
            return self.temp_sensor.get_temp()[0]
        return 0.0


class StreamingContext:

    def __init__(self, scanning_probe, callback):
        self.scanner = scanning_probe
        self.callback = callback
        self.reactor = scanning_probe.printer.get_reactor()
        self.done_completion = None
        self.stream_enabled = False

    def __enter__(self):
        self.stream_enabled = True
        self.scanner.add_client(self._bulk_callback)

    def __exit__(self, type=None, value=None, tb=None):
        self.done_completion = self.reactor.completion()
        self.stream_enabled = False
        self.done_completion.wait()
        self.done_completion = None

    def _bulk_callback(self, msg):
        if not self.stream_enabled:
            if self.done_completion is not None:
                self.done_completion.complete(None)
            return False
        self.callback(msg)
        return True


MAX_HIT_DIST = 2.0
MM_WIN_SPEED = 125

class SamplingMode:
    STANDARD = 0
    WEIGHTED = 1
    CENTERED = 2
    LINEAR = 3

    @staticmethod
    def from_str(sampling_type):
        return getattr(SamplingMode, sampling_type.upper(), 0)

    def to_str(sampling_idx):
        return {val: name.lower() for name, val in SamplingMode.__dict__.items() if name[0].isupper() if isinstance(val, int)}.get(sampling_idx, "standard")


class ScanStopEndSignal(Exception):
    pass


class ProbeScanHelper:

    def __init__(self, probe_points, printer, points, use_offsets, speed, horizontal_move_z, finalize_cb):
        self.probe_points = probe_points
        self.printer = printer
        self.points = points
        self.probe = self.printer.lookup_object("probe")
        self.probe_offsets = self.probe.get_offsets()
        self.use_offsets = use_offsets
        self.speed = speed
        self.scan_height = horizontal_move_z
        self.finalize_callback = finalize_cb
        self.min_time_window = 0
        self.max_time_window = 0
        self.sampling_mode = SamplingMode.STANDARD
        self.reset()

    def reset(self):
        self.samples_pending = []
        self.lookahead_index = 0
        self.sample_index = 0

    def perform_scan(self, gcmd):
        mode = gcmd.get("SCAN_MODE", "rapid")
        speed = gcmd.get_float("SCAN_SPEED", self.speed)
        default_sm = "centered" if mode == "detailed" else "standard"
        sampling_mode = gcmd.get("SAMPLES_RESULT", default_sm)
        self.sampling_mode = SamplingMode.from_str(sampling_mode)
        gcmd.respond_info("Beginning %s surface scan at height %.2f, sampling mode %s..." % (
         mode, self.scan_height, SamplingMode.to_str(self.sampling_mode)))
        while True:
            self.reset()
            if mode == "rapid":
                results = self._rapid_scan(gcmd, speed)
            else:
                results = self._detailed_scan(gcmd, speed)
            offsets = list(self.probe_offsets)
            offsets[2] = 0
            ret = self.finalize_callback(tuple(offsets), results)
            if ret != "retry":
                break

    def _detailed_scan(self, gcmd, speed):
        scanner = self.printer.lookup_object(self.probe.get_probe_name())
        toolhead = self.printer.lookup_object("toolhead")
        sample_time = gcmd.get_float("SAMPLE_TIME", 0.1, above=0.1)
        sample_time += 0.05
        self._raise_tool(gcmd)
        reactor = self.printer.get_reactor()
        self.min_time_window = -0.05
        self.max_time_window = sample_time
        with scanner.stream(self._on_bulk_data_collected):
            for (idx, pos) in enumerate(self.points):
                if self.probe_points.is_mcu_stop():
                    raise ScanStopEndSignal()
                else:
                    pos = self._apply_offsets(pos[:2])
                    toolhead.manual_move(pos, speed)
                    if idx == 0:
                        self._move_to_scan_height(gcmd)
                    toolhead.register_lookahead_callback(self._lookahead_callback)
                    toolhead.dwell(sample_time)

            toolhead.wait_moves()
            reactor.pause(reactor.monotonic() + 0.2)
        return self._process_batch_measurements(gcmd)

    def _rapid_scan(self, gcmd, speed):
        scanner = self.printer.lookup_object(self.probe.get_probe_name())
        toolhead = self.printer.lookup_object("toolhead")
        scale = max(0, 1 - speed / MM_WIN_SPEED) + 1
        hit_dist = min(MAX_HIT_DIST, scale * speed / MM_WIN_SPEED)
        window = hit_dist / speed
        gcmd.respond_info("Sample hit distance +/- %.4fmm, time window +/- ms %.4f" % (
         hit_dist, window * 1000))
        self.min_time_window = self.max_time_window = window
        self._raise_tool(gcmd)
        reactor = self.printer.get_reactor()
        with scanner.stream(self._on_bulk_data_collected):
            ptgen = getattr(self.points, "iter_rapid", self._rapid_default_gen)
            for (idx, (pos, is_probe_pt)) in enumerate(ptgen()):
                if self.probe_points.is_mcu_stop():
                    raise ScanStopEndSignal()
                else:
                    pos = self._apply_offsets(pos[:2])
                    toolhead.manual_move(pos, speed)
                    if idx == 0:
                        self._move_to_scan_height(gcmd)
                if is_probe_pt:
                    toolhead.register_lookahead_callback(self._lookahead_callback)
                toolhead.wait_moves()
                reactor.pause(reactor.monotonic() + 0.2)

        return self._process_batch_measurements(gcmd)

    def _rapid_default_gen(self):
        for pt in self.points:
            yield (
             pt, True)

    def _raise_tool(self, gcmd):
        toolhead = self.printer.lookup_object("toolhead")
        cur_pos = toolhead.get_position()
        if cur_pos[2] >= self.scan_height:
            return
        lift_speed = self.probe.get_lift_speed(gcmd)
        cur_pos[2] = self.scan_height + 0.5
        toolhead.manual_move(cur_pos, lift_speed)

    def _move_to_scan_height(self, gcmd):
        toolhead = self.printer.lookup_object("toolhead")
        cur_pos = toolhead.get_position()
        lift_speed = self.probe.get_lift_speed(gcmd)
        probe_speed = self.probe.get_probe_speed(gcmd)
        cur_pos[2] = self.scan_height + 0.5
        toolhead.manual_move(cur_pos, lift_speed)
        cur_pos[2] = self.scan_height
        toolhead.manual_move(cur_pos, probe_speed)
        toolhead.dwell(abs(self.min_time_window) + 0.01)

    def _apply_offsets(self, point):
        if self.use_offsets:
            return [pos - ofs for pos, ofs in zip(point, self.probe_offsets)]
        return point

    def _lookahead_callback(self, print_time):
        pt = self._apply_offsets(self.points[self.lookahead_index])
        self.lookahead_index += 1
        self.samples_pending.append((print_time, pt, []))

    def _on_bulk_data_collected(self, msg):
        idx = self.sample_index
        if len(self.samples_pending) < idx + 1:
            return
        (req_time, _, z_samples) = self.samples_pending[idx]
        data = msg["data"]
        for (ptime, _, z) in data:
            while ptime > req_time + self.max_time_window:
                self.sample_index += 1
                idx = self.sample_index
                if len(self.samples_pending) < idx + 1:
                    return None
                else:
                    (req_time, _, z_samples) = self.samples_pending[idx]

            if ptime < req_time - self.min_time_window:
                pass
            else:
                z_samples.append((ptime, z))

    def _process_batch_measurements(self, gcmd):
        results = []
        if len(self.samples_pending) != len(self.points):
            raise gcmd.error("Position sample length does not match number of points requested, received: %d, requested %d" % (
             len(self.samples_pending), len(self.points)))
        last_sample = (0, 0, [])
        overlaps = set()
        for (idx, sample) in enumerate(self.samples_pending):
            min_smample_time = sample[0] - self.min_time_window
            z_samples = sample[2]
            for zs in last_sample[2]:
                if zs in z_samples:
                    pass
                else:
                    if zs[0] >= min_smample_time:
                        z_samples.append(zs)
                        overlaps.add(idx)
                    z_samples.sort(key=(lambda s: s[0]))
                    results.append(self._process_samples(gcmd, sample))
                    last_sample = sample

        if overlaps:
            logging.info("Detected %d overlapping samples" % (len(overlaps),))
        return results

    def _process_samples(self, gcmd, sample):
        (move_time, pos, z_samples) = sample
        valid_samples = []
        for sample in z_samples:
            if abs(sample[1]) > 99.0:
                gcmd.respond_info("Z-sample at time %.6f for position (%.6f, %.6f) is invalid.  Verify that 'horizontal_move_z' not too high." % (
                 sample[0], pos[0], pos[1]))
            else:
                valid_samples.append(sample)

        sample_len = len(valid_samples)
        if sample_len == 0:
            raise gcmd.error("No valid measurements found at coordinate : %s" % (
             repr(pos),))
        if self.sampling_mode == SamplingMode.CENTERED:
            z_vals = sorted([s[1] for s in valid_samples])
            discard_count = len(z_vals) // 4
            keep_vals = z_vals[discard_count:-discard_count]
            sample_len = len(keep_vals)
            z_height = sum(keep_vals) / sample_len
        elif self.sampling_mode == SamplingMode.WEIGHTED:
            time_diffs = [abs(move_time - s[0]) for s in valid_samples]
            max_diff = max(time_diffs)
            weights = [max_diff / diff for diff in time_diffs]
            total_weight = sum(weights)
            z_height = 0
            for (weight, sample) in zip(weights, valid_samples):
                factor = weight / total_weight
                z_height += sample[1] * factor

        elif self.sampling_mode == SamplingMode.LINEAR:
            sample_times = [s[0] for s in valid_samples]
            idx = bisect.bisect(sample_times, move_time)
            if idx == 0:
                z_height = valid_samples[0][1]
            elif idx == sample_len:
                z_height = valid_samples[-1][1]
            else:
                (min_time, min_z) = valid_samples[idx - 1]
                (max_time, max_z) = valid_samples[idx]
                time_diff = max_time - min_time
                time_from_min = move_time - min_time
                t = min(1, max(0, time_from_min / time_diff))
                z_height = (1.0 - t) * min_z + t * max_z
        else:
            z_height = sum([s[1] for s in valid_samples]) / sample_len
        probed_z = self.scan_height - z_height
        atc = self.printer.lookup_object("axis_twist_compensation", None)
        if atc is not None:
            z_comp = atc.get_z_compensation_value(pos)
            probed_z += z_comp
        gcmd.respond_info("Scan at (%.4f, %.4f) is z=%.6f, height=%.6f, sample count=%d" % (
         pos[0], pos[1], probed_z, z_height, sample_len))
        return [
         pos[0], pos[1], probed_z]


def load_config(config):
    return PrinterCurrentProbe(config)

